@page "/chat"
@using sv_7b8637896cbe436bbfec0c66eb8542d8.Services
@inject IChatService ChatService
@inject IJSRuntime JS
@rendermode InteractiveServer

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    @* ── Left Sidebar: Channel List ── *@
    <aside class="chat-sidebar">
        <h4 class="sidebar-title">Channels</h4>
        <ul class="channel-list">
            @foreach (var channel in channels)
            {
                <li class="channel-item @(channel.Id == activeChannelId ? "active" : "")"
                    @onclick="() => SelectChannelAsync(channel)">
                    <div class="channel-header-row">
                        <span class="channel-name"># @channel.Name</span>
                        @if (channel.UnreadCount > 0)
                        {
                            <span class="unread-badge">@channel.UnreadCount</span>
                        }
                    </div>
                    @if (!string.IsNullOrWhiteSpace(channel.Description))
                    {
                        <span class="channel-description">@Truncate(channel.Description, 50)</span>
                    }
                </li>
            }
        </ul>
    </aside>

    @* ── Main Message Area ── *@
    <section class="chat-main @(threadOpen ? "thread-open" : "")">
        @if (activeChannel is not null)
        {
            <div class="main-header">
                <h5 class="main-channel-name"># @activeChannel.Name</h5>
                <span class="main-channel-desc">@activeChannel.Description</span>
            </div>

            <div class="message-list" @ref="messageListRef" @onscroll="HandleScrollAsync">
                @if (loadingOlder)
                {
                    <div class="loading-indicator">Loading older messages…</div>
                }
                @foreach (var msg in messages)
                {
                    <div class="message-row" @key="msg.Id">
                        <div class="message-bubble">
                            <div class="message-meta">
                                <span class="msg-author">@msg.Author</span>
                                <span class="msg-time">@FormatRelativeTime(msg.SentAt)</span>
                            </div>
                            <div class="msg-content">@msg.Content</div>

                            @if (msg.Reactions.Count > 0)
                            {
                                <div class="reaction-row">
                                    @foreach (var r in msg.Reactions)
                                    {
                                        <button class="reaction-badge" title="@string.Join(", ", r.Users)"
                                                @onclick="() => AddReactionAsync(msg.Id, r.Emoji)">
                                            @r.Emoji @r.Users.Count
                                        </button>
                                    }
                                </div>
                            }

                            @{ var threadInfo = threadSummaries.GetValueOrDefault(msg.Id); }
                            @if (threadInfo is not null)
                            {
                                <button class="thread-link" @onclick="() => OpenThreadAsync(msg)">
                                    @threadInfo.ReplyCount @(threadInfo.ReplyCount == 1 ? "reply" : "replies")
                                </button>
                            }
                        </div>

                        <div class="message-actions">
                            <button class="action-btn" title="Reply in thread" @onclick="() => OpenThreadAsync(msg)">💬</button>
                            <button class="action-btn" title="Add reaction" @onclick="() => ToggleEmojiPicker(msg.Id)">😀</button>
                        </div>

                        @if (emojiPickerMessageId == msg.Id)
                        {
                            <div class="emoji-picker">
                                @foreach (var emoji in commonEmojis)
                                {
                                    <button class="emoji-option" @onclick="() => PickEmojiAsync(msg.Id, emoji)">@emoji</button>
                                }
                            </div>
                        }
                    </div>
                }
            </div>

            <div class="message-input-area">
                <textarea class="message-input" rows="2" placeholder="Message #@activeChannel.Name"
                          @bind="newMessageText" @bind:event="oninput"
                          @onkeydown="HandleMainKeyDownAsync" />
                <button class="send-btn" disabled="@string.IsNullOrWhiteSpace(newMessageText)"
                        @onclick="SendMainMessageAsync">Send</button>
            </div>
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </section>

    @* ── Right Panel: Thread View ── *@
    @if (threadOpen && threadRootMessage is not null)
    {
        <aside class="chat-thread-panel">
            <div class="thread-header">
                <h5>Thread</h5>
                <button class="close-thread-btn" @onclick="CloseThread">✕</button>
            </div>
            <div class="thread-root-quote">
                <span class="msg-author">@threadRootMessage.Author</span>
                <span class="msg-time">@FormatRelativeTime(threadRootMessage.SentAt)</span>
                <p class="msg-content">@threadRootMessage.Content</p>
            </div>

            <div class="thread-replies">
                @foreach (var reply in threadReplies)
                {
                    <div class="message-bubble" @key="reply.Id">
                        <div class="message-meta">
                            <span class="msg-author">@reply.Author</span>
                            <span class="msg-time">@FormatRelativeTime(reply.SentAt)</span>
                        </div>
                        <div class="msg-content">@reply.Content</div>

                        @if (reply.Reactions.Count > 0)
                        {
                            <div class="reaction-row">
                                @foreach (var r in reply.Reactions)
                                {
                                    <button class="reaction-badge" title="@string.Join(", ", r.Users)"
                                            @onclick="() => AddReactionAsync(reply.Id, r.Emoji)">
                                        @r.Emoji @r.Users.Count
                                    </button>
                                }
                            </div>
                        }
                    </div>
                }
            </div>

            <div class="message-input-area">
                <textarea class="message-input" rows="2" placeholder="Reply…"
                          @bind="threadReplyText" @bind:event="oninput"
                          @onkeydown="HandleThreadKeyDownAsync" />
                <button class="send-btn" disabled="@string.IsNullOrWhiteSpace(threadReplyText)"
                        @onclick="SendThreadReplyAsync">Reply</button>
            </div>
        </aside>
    }
</div>

@code {
    private List<Channel> channels = new();
    private List<Message> messages = new();
    private List<Message> threadReplies = new();
    private Dictionary<int, ThreadSummary> threadSummaries = new();

    private Channel? activeChannel;
    private int activeChannelId;
    private Message? threadRootMessage;
    private bool threadOpen;
    private bool loadingOlder;
    private bool allOlderLoaded;
    private int? emojiPickerMessageId;

    private string newMessageText = string.Empty;
    private string threadReplyText = string.Empty;

    private ElementReference messageListRef;

    private const int PageSize = 30;
    private static readonly string[] commonEmojis = ["👍", "❤️", "😂", "🎉", "🚀", "👀"];

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
    }

    private async Task SelectChannelAsync(Channel channel)
    {
        activeChannel = channel;
        activeChannelId = channel.Id;
        messages.Clear();
        threadSummaries.Clear();
        allOlderLoaded = false;
        emojiPickerMessageId = null;

        var loaded = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        messages = loaded;
        BuildThreadSummaries();

        await ChatService.MarkChannelReadAsync(channel.Id);
        await RefreshChannelUnread(channel.Id);
        await ScrollToBottom();
    }

    private async Task HandleScrollAsync()
    {
        if (loadingOlder || allOlderLoaded) return;

        var scrollTop = await JS.InvokeAsync<double>("eval", "document.querySelector('.message-list')?.scrollTop ?? 1");
        if (scrollTop < 50)
        {
            await LoadOlderMessagesAsync();
        }
    }

    private async Task LoadOlderMessagesAsync()
    {
        if (activeChannel is null || loadingOlder || allOlderLoaded) return;

        loadingOlder = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(activeChannel.Id, messages.Count, PageSize);
        if (older.Count < PageSize)
        {
            allOlderLoaded = true;
        }
        messages.InsertRange(0, older);
        BuildThreadSummaries();

        loadingOlder = false;
    }

    private async Task SendMainMessageAsync()
    {
        if (activeChannel is null || string.IsNullOrWhiteSpace(newMessageText)) return;

        var sent = await ChatService.SendMessageAsync(activeChannel.Id, newMessageText.Trim(), null);
        messages.Add(sent);
        newMessageText = string.Empty;
        await ScrollToBottom();
    }

    private async Task HandleMainKeyDownAsync(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendMainMessageAsync();
        }
    }

    private async Task OpenThreadAsync(Message rootMessage)
    {
        threadRootMessage = rootMessage;
        threadOpen = true;
        emojiPickerMessageId = null;

        threadReplies = await ChatService.GetThreadAsync(rootMessage.Id);
    }

    private void CloseThread()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadReplies.Clear();
    }

    private async Task SendThreadReplyAsync()
    {
        if (threadRootMessage is null || string.IsNullOrWhiteSpace(threadReplyText)) return;

        var reply = await ChatService.SendMessageAsync(
            threadRootMessage.ChannelId, threadReplyText.Trim(), threadRootMessage.Id);
        threadReplies.Add(reply);
        threadReplyText = string.Empty;

        // Update thread summary
        var summary = new ThreadSummary(threadRootMessage.Id, threadReplies.Count, reply.SentAt);
        threadSummaries[threadRootMessage.Id] = summary;
    }

    private async Task HandleThreadKeyDownAsync(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendThreadReplyAsync();
        }
    }

    private void ToggleEmojiPicker(int messageId)
    {
        emojiPickerMessageId = emojiPickerMessageId == messageId ? null : messageId;
    }

    private async Task PickEmojiAsync(int messageId, string emoji)
    {
        emojiPickerMessageId = null;
        await AddReactionAsync(messageId, emoji);
    }

    private async Task AddReactionAsync(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);

        // Refresh messages to reflect updated reactions
        if (activeChannel is not null)
        {
            var refreshed = await ChatService.GetMessagesAsync(activeChannel.Id, 0, messages.Count);
            messages = refreshed;
        }
    }

    private void BuildThreadSummaries()
    {
        threadSummaries.Clear();
        var replies = messages.Where(m => m.ReplyToId.HasValue).ToList();
        foreach (var group in replies.GroupBy(m => m.ReplyToId!.Value))
        {
            threadSummaries[group.Key] = new ThreadSummary(
                group.Key,
                group.Count(),
                group.Max(m => m.SentAt));
        }
    }

    private async Task RefreshChannelUnread(int channelId)
    {
        var refreshed = await ChatService.GetChannelsAsync();
        channels = refreshed;
    }

    private async Task ScrollToBottom()
    {
        await Task.Yield();
        await JS.InvokeVoidAsync("eval",
            "let el = document.querySelector('.message-list'); if(el) el.scrollTop = el.scrollHeight;");
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt.ToUniversalTime();

        if (diff.TotalSeconds < 60) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }

    private static string Truncate(string text, int maxLength)
    {
        return text.Length <= maxLength ? text : text[..maxLength] + "…";
    }
}

